#import "xenia/ui/ios/launcher/ios_compat_formatting.h"

#include <iterator>

// Autogenerated by `xb premake`.
#include "version.h"

#ifndef XE_BUILD_VERSION
#define XE_BUILD_VERSION "1.0.0"
#endif

#ifndef XE_BUILD_NUMBER
#define XE_BUILD_NUMBER "0"
#endif

#ifndef XE_BUILD_COMMIT_SHORT
#define XE_BUILD_COMMIT_SHORT ""
#endif

#import "xenia/ui/ios/shared/ios_theme.h"
#import "xenia/ui/ios/shared/ios_view_helpers.h"

namespace {

// Compatibility taxonomy: status and perf share the same "code → label /
// color / rank" lookup shape, so a single struct + generic FindByCode() drive
// every accessor below. `hex_color == 0` means
// render with [XeniaTheme textMuted]; `rank` is only meaningful for
// statuses (higher = "more playable").
struct CompatTaxonomyEntry {
  NSString* code;
  NSString* label;
  uint32_t hex_color;
  NSInteger rank;
};

const CompatTaxonomyEntry kCompatStatuses[] = {
    {@"playable", @"Playable", 0x34d399, 4}, {@"ingame", @"In-Game", 0x60a5fa, 3},
    {@"intro", @"Intro", 0xfbbf24, 2},       {@"loads", @"Loads", 0xfb923c, 1},
    {@"nothing", @"Nothing", 0xf87171, 0},
};

const CompatTaxonomyEntry kCompatStatusUntested = {@"untested", @"Untested", 0, 0};

const CompatTaxonomyEntry kCompatPerfs[] = {
    {@"great", @"Great", 0x34d399, 0},
    {@"ok", @"Okay", 0x60a5fa, 0},
    {@"poor", @"Poor", 0xfbbf24, 0},
    {@"n/a", @"N/A", 0, 0},
};

UIColor* ColorFromTaxonomy(const CompatTaxonomyEntry& entry) {
  return entry.hex_color ? XEColorFromHexRGB(entry.hex_color) : [XeniaTheme textMuted];
}

const CompatTaxonomyEntry* FindByCode(const CompatTaxonomyEntry* entries, size_t count,
                                      NSString* code) {
  for (size_t i = 0; i < count; ++i) {
    if ([entries[i].code isEqualToString:code]) {
      return &entries[i];
    }
  }
  return nullptr;
}

const CompatTaxonomyEntry* FindCompatStatus(NSString* code) {
  if (const CompatTaxonomyEntry* entry =
          FindByCode(kCompatStatuses, std::size(kCompatStatuses), code)) {
    return entry;
  }
  if ([code isEqualToString:kCompatStatusUntested.code]) {
    return &kCompatStatusUntested;
  }
  return nullptr;
}

const CompatTaxonomyEntry* FindCompatPerf(NSString* code) {
  return FindByCode(kCompatPerfs, std::size(kCompatPerfs), code);
}

}  // namespace

UIColor* xe_compat_status_color(NSString* status) {
  const CompatTaxonomyEntry* entry = FindCompatStatus(status);
  return entry ? ColorFromTaxonomy(*entry) : [XeniaTheme textMuted];
}

NSString* xe_compat_status_label(NSString* status) {
  const CompatTaxonomyEntry* entry = FindCompatStatus(status);
  return entry ? entry->label
               : NSLocalizedString(@"Unknown", @"compat formatting: user-visible text");
}

UIColor* xe_compat_perf_color(NSString* perf) {
  const CompatTaxonomyEntry* entry = FindCompatPerf(perf);
  return entry ? ColorFromTaxonomy(*entry) : [XeniaTheme textMuted];
}

NSString* xe_compat_perf_label(NSString* perf) {
  const CompatTaxonomyEntry* entry = FindCompatPerf(perf);
  return entry ? entry->label
               : NSLocalizedString(@"Unknown", @"compat formatting: user-visible text");
}

NSString* xe_format_iso_date(NSString* iso) {
  if (!iso || iso.length < 10) {
    return iso ?: @"";
  }
  static NSDateFormatter* parser = nil;
  static NSDateFormatter* date_only_parser = nil;
  static NSDateFormatter* formatter = nil;
  static dispatch_once_t once;
  dispatch_once(&once, ^{
    parser = [[NSDateFormatter alloc] init];
    parser.dateFormat = @"yyyy-MM-dd'T'HH:mm:ss";
    parser.locale = [[[NSLocale alloc] initWithLocaleIdentifier:@"en_US_POSIX"] autorelease];
    date_only_parser = [[NSDateFormatter alloc] init];
    date_only_parser.dateFormat = @"yyyy-MM-dd";
    date_only_parser.locale =
        [[[NSLocale alloc] initWithLocaleIdentifier:@"en_US_POSIX"] autorelease];
    formatter = [[NSDateFormatter alloc] init];
    formatter.dateStyle = NSDateFormatterMediumStyle;
    formatter.timeStyle = NSDateFormatterNoStyle;
  });

  NSString* trimmed = [iso substringToIndex:MIN(iso.length, (NSUInteger)19)];
  NSDate* date = [parser dateFromString:trimmed];
  if (!date) {
    date = [date_only_parser dateFromString:[iso substringToIndex:MIN(iso.length, (NSUInteger)10)]];
  }
  return date ? [formatter stringFromDate:date]
              : [iso substringToIndex:MIN(iso.length, (NSUInteger)10)];
}

NSString* xe_platform_display_text(NSString* platform, NSString* os_version) {
  if (![platform isKindOfClass:[NSString class]] || platform.length == 0) {
    return @"";
  }
  NSString* platform_name = [platform isEqualToString:@"ios"]     ? @"iOS"
                            : [platform isEqualToString:@"macos"] ? @"macOS"
                                                                  : platform;
  if (![os_version isKindOfClass:[NSString class]] || os_version.length == 0) {
    return platform_name;
  }
  return [NSString stringWithFormat:@"%@ %@", platform_name, os_version];
}

NSString* xe_string_from_object(id value) {
  return [value isKindOfClass:[NSString class]] ? (NSString*)value : nil;
}

NSDictionary* xe_dictionary_from_object(id value) {
  return [value isKindOfClass:[NSDictionary class]] ? (NSDictionary*)value : nil;
}

NSInteger xe_compat_status_rank(NSString* status) {
  const CompatTaxonomyEntry* entry = FindCompatStatus(status);
  return entry ? entry->rank : 0;
}

// A build as people name it: "2.2 (11357)".
static NSString* xe_build_version_label(NSDictionary* build_info) {
  NSString* app_version = xe_string_from_object(build_info[@"appVersion"]);
  NSString* build_number = xe_string_from_object(build_info[@"buildNumber"]);
  if (app_version.length > 0 && build_number.length > 0) {
    return [NSString stringWithFormat:@"%@ (%@)", app_version, build_number];
  }
  if (app_version.length > 0) {
    return app_version;
  }
  if (build_number.length > 0) {
    return [NSString
        stringWithFormat:NSLocalizedString(@"Build %@", @"compat formatting: user-visible text"),
                         build_number];
  }
  return nil;
}

NSString* xe_compat_build_label(NSDictionary* build_info) {
  return xe_build_version_label(build_info);
}

NSString* xe_user_facing_build_label(NSDictionary* build_info) {
  return xe_compat_build_label(build_info)
             ?: NSLocalizedString(@"Unknown Build", @"compat formatting: user-visible text");
}

NSDictionary* xe_compat_build_info_from_entry(NSDictionary* entry) {
  if (!entry) {
    return nil;
  }
  NSDictionary* nested = xe_dictionary_from_object(entry[@"build"]);
  NSString* app_version = xe_string_from_object(nested[@"appVersion"]);
  NSString* build_number = xe_string_from_object(nested[@"buildNumber"]);
  NSString* commit_short = xe_string_from_object(nested[@"commitShort"]);

  NSMutableDictionary* build = [NSMutableDictionary dictionary];
  if (app_version.length > 0) {
    build[@"appVersion"] = app_version;
  }
  if (build_number.length > 0) {
    build[@"buildNumber"] = build_number;
  }
  if (commit_short.length > 0) {
    build[@"commitShort"] = commit_short;
  }
  return build.count > 0 ? build : nil;
}

NSDictionary* xe_current_compat_report_build_info(void) {
  static NSDictionary* build_info = nil;
  static dispatch_once_t once_token;
  dispatch_once(&once_token, ^{
    NSBundle* bundle = [NSBundle mainBundle];
    NSString* app_version =
        xe_string_from_object([bundle objectForInfoDictionaryKey:@"CFBundleShortVersionString"]);
    NSString* build_number =
        xe_string_from_object([bundle objectForInfoDictionaryKey:@"CFBundleVersion"]);
    NSString* compiled_app_version = [NSString stringWithUTF8String:XE_BUILD_VERSION];
    NSString* compiled_build_number = [NSString stringWithUTF8String:XE_BUILD_NUMBER];
    BOOL uses_placeholder_bundle_version =
        (app_version.length == 0 || [app_version isEqualToString:@"1.0"]) &&
        (build_number.length == 0 || [build_number isEqualToString:@"1"]);
    if (uses_placeholder_bundle_version) {
      app_version = compiled_app_version.length > 0 ? compiled_app_version : @"1.0.0";
      build_number = compiled_build_number.length > 0 ? compiled_build_number : @"0";
    } else {
      if (app_version.length == 0) {
        app_version = compiled_app_version.length > 0 ? compiled_app_version : @"1.0.0";
      }
      if (build_number.length == 0) {
        build_number = compiled_build_number.length > 0 ? compiled_build_number : @"0";
      }
    }

    NSString* commit_short = [NSString stringWithUTF8String:XE_BUILD_COMMIT_SHORT];
    build_info = [@{
      @"appVersion" : app_version,
      @"buildNumber" : build_number,
      @"commitShort" : commit_short,
    } copy];
  });
  return build_info;
}

NSArray<NSString*>* xe_compat_statuses(void) {
  NSMutableArray<NSString*>* codes = [NSMutableArray arrayWithCapacity:std::size(kCompatStatuses)];
  for (const auto& entry : kCompatStatuses) {
    [codes addObject:entry.code];
  }
  return codes;
}

NSArray<NSString*>* xe_compat_status_labels(void) {
  NSMutableArray<NSString*>* labels = [NSMutableArray arrayWithCapacity:std::size(kCompatStatuses)];
  for (const auto& entry : kCompatStatuses) {
    [labels addObject:entry.label];
  }
  return labels;
}

NSArray<NSString*>* xe_compat_perfs(void) {
  NSMutableArray<NSString*>* codes = [NSMutableArray arrayWithCapacity:std::size(kCompatPerfs)];
  for (const auto& entry : kCompatPerfs) {
    [codes addObject:entry.code];
  }
  return codes;
}

// Picker labels keep "OK" (vs. xe_compat_perf_label's "Okay") so the report
// submission buttons show the short form the website also uses.
NSArray<NSString*>* xe_compat_perf_labels(void) {
  return @[
    NSLocalizedString(@"Great", @"compat formatting: user-visible text"),
    NSLocalizedString(@"OK", @"compat formatting: user-visible text"),
    NSLocalizedString(@"Poor", @"compat formatting: user-visible text"), @"N/A"
  ];
}

CGFloat xe_compat_hero_height_for_width(CGFloat width, UIImage* background_art) {
  CGFloat hero_width = MAX(width, 0.0);
  if (hero_width <= 0.0) {
    return 286.0;
  }
  // When background art is available, derive height from the image aspect
  // ratio so the hero card shows more of the artwork.
  if (background_art && background_art.size.width > 0.0 && background_art.size.height > 0.0) {
    CGFloat image_aspect = background_art.size.width / background_art.size.height;
    CGFloat derived = floor(hero_width / image_aspect);
    return MIN(360.0, MAX(240.0, derived));
  }
  return MIN(360.0, MAX(286.0, floor(hero_width * 0.74)));
}
